import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  世界信息: z.object({
    时间: z.string(),
    地点: z.string()
  }),

  Alyssa: z.object({
    关系状态: z.enum(['观察期', '试探期', '臣服期', '依恋期', '危机期']),
    信任度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
    药物戒断状态: z.enum(['用药稳态', '早期戒断', '高峰戒断', '消退期', '稽延性戒断'])
  }),

  任务: z.object({
    任务名称: z.string(),
    任务内容: z.string(),
    任务报酬: z.coerce.number(),
    任务状态: z.enum(['未接取', '进行中', '已完成', '已失败'])
  }),

  存款: z.object({
    当前存款额度: z.coerce.number()
  })
});

$(() => {
  registerMvuSchema(Schema);
})

