    <script type="module">
        /* 战术终端配色映射：关系状态 */
        const RELATIONSHIP_BADGE = {
            观察期: 'badge-neutral',
            试探期: 'badge-warn',
            臣服期: 'badge-info',
            依恋期: 'badge-attach',
            危机期: 'badge-critical'
        };

        /* 战术终端配色映射：药物戒断状态 */
        const WITHDRAWAL_BADGE = {
            用药稳态: 'badge-stable',
            早期戒断: 'badge-warn',
            高峰戒断: 'badge-critical',
            消退期: 'badge-warn',
            稽延性戒断: 'badge-info'
        };

        /* 战术终端配色映射：任务状态 */
        const TASK_BADGE = {
            未接取: 'badge-neutral',
            进行中: 'badge-info',
            已完成: 'badge-stable',
            已失败: 'badge-critical'
        };

        /* 根据映射表设置徽章的文本与样式 */
        function setBadge($el, value, map) {
            $el.text(value || 'N/A');
            $el.removeClass('badge-neutral badge-stable badge-warn badge-critical badge-info badge-attach');
            $el.addClass(map[value] || 'badge-neutral');
        }

        /* 更新信任度进度条 */
        function updateMeter(fillId, valueId, rawValue, min = 0, max = 100) {
            const numericValue = parseFloat(rawValue);
            if (!isNaN(numericValue)) {
                const clampedValue = _.clamp(numericValue, min, max);
                const percentage = max - min === 0 ? 0 : ((clampedValue - min) / (max - min)) * 100;
                $(`#${valueId}`).text(clampedValue);
                $(`#${fillId}`).css('width', `${percentage}%`);
            } else {
                $(`#${valueId}`).text(rawValue);
            }
        }

        /* 填充状态栏数据 */
        function populateCharacterData() {
            try {
                const all_variables = getAllVariables();
                const characterData = all_variables.stat_data;

                if (!characterData) {
                    $('#status-card').html("<div class='error-tip'>[ NO DATA LINK ] 无法加载状态数据</div>");
                    return;
                }

                /* 世界信息 */
                $('#current-time').text(_.get(characterData, '世界信息.时间', 'N/A'));
                $('#current-location').text(substitudeMacros(_.get(characterData, '世界信息.地点', 'N/A')));

                /* Alyssa 状态 */
                setBadge($('#alyssa-relationship'), _.get(characterData, 'Alyssa.关系状态', 'N/A'), RELATIONSHIP_BADGE);
                setBadge($('#alyssa-withdrawal'), _.get(characterData, 'Alyssa.药物戒断状态', 'N/A'), WITHDRAWAL_BADGE);
                updateMeter('alyssa-trust-bar', 'alyssa-trust', _.get(characterData, 'Alyssa.信任度', 0), 0, 100);

                /* 当前委托 */
                const taskName = substitudeMacros(_.get(characterData, '任务.任务名称', ''));
                const taskContent = substitudeMacros(_.get(characterData, '任务.任务内容', ''));
                $('#task-name').text(taskName || '暂无委托');
                $('#task-content').text(taskContent || '——');
                $('#task-reward').text(Number(_.get(characterData, '任务.任务报酬', 0)).toLocaleString());
                setBadge($('#task-status'), _.get(characterData, '任务.任务状态', 'N/A'), TASK_BADGE);

                /* 存款 */
                $('#deposit-amount').text(Number(_.get(characterData, '存款.当前存款额度', 0)).toLocaleString());
            } catch (error) {
                $('#status-card').html(`<div class='error-tip'>状态栏加载出错: ${error.message}</div>`);
            }
        }

        /* 初始化 */
        async function init() {
            await waitGlobalInitialized('Mvu');
            populateCharacterData();
        }

        $(errorCatched(init));
    </script>
</head>
